import sqlite3

def solve(data: dict) -> dict:
    db = sqlite3.connect(":memory:")
    db.execute("CREATE TABLE document (id INTEGER PRIMARY KEY, value TEXT, version INTEGER)")
    db.execute("INSERT INTO document VALUES (1, ?, ?)", (data["value"], data["version"]))
